class Solution:

	def atoi(self, string):
		num = 0
		negative = 1
		start = 0
		for char in string:
			if char == '-' and start == 1:
				num = 'N'
				break
			if char == '-':
				if negative == -1:
					num = 'N'
					break
				negative = -1
				continue
			elif not char.isnumeric():
				num = 'N'
				break
			else:
				num = num * 10 + int(char)
			start = 1
		if num == 'N':
			return -1
		return num * negative
